	Description: A library to provide localizations for spells.
	Dependencies: LibStub, AceLocale-3.0
	Note: Ace3v port of Babble-Spell-2.2, API-compatible. The Ace2 original was an
	      AceLocale-2.2 instance registered into AceLibrary; this is a plain LibStub
	      library that reproduces the instance API on top of AceLocale-3.0.
]]

local MAJOR_VERSION, MINOR_VERSION = "LibBabble-Spell-2.2", 1

local BabbleSpell = LibStub:NewLibrary(MAJOR_VERSION, MINOR_VERSION)

if not BabbleSpell then return end -- No upgrade needed

local AceLocale = LibStub("AceLocale-3.0")

-- Ace3v: 72 names that are not in the 1.12 client (TBC spells and a private
-- server's custom professions) are left out of every locale; see the README.

local L = AceLocale:NewLocale(MAJOR_VERSION, "enUS", true, true)
