local reverse

local availableLocales = {}
for _, locale in ipairs({"enUS", "ruRU", "esES", "deDE", "frFR", "zhCN", "zhTW", "koKR"}) do
	availableLocales[locale] = true
end

local gameLocale = GAME_LOCALE or GetLocale()
local currentLocale = availableLocales[gameLocale] and gameLocale or "enUS"

local next, rawget, error, tostring, type = next, rawget, error, tostring, type
local strfind, strlower, strgsub = string.find, string.lower, string.gsub

-- Ace3v: AceLibrary injected :argCheck into every library it registered; LibStub
-- does not. The argument number is kept as it was, counting `self`.
local function argCheck(value, num, kind)
	local t = type(value)
	if t ~= kind then
		error(string.format("%s: bad argument #%d (%s expected, got %s)",
			MAJOR_VERSION, num, kind, t), 3)
	end
end

-- Ace3v: several spells share one localized name. AceLocale-2.2 kept whichever
-- came last in its hash order; the alphabetically first English name is kept
-- here, so both clients give the same answer.
local function initReverse()
	reverse = {}
	for base, localized in next, translations do
		local old = reverse[localized]
		if not old or base < old then
			reverse[localized] = base
		end
	end
end

------------------------------------------------
-- The AceLocale-2.2 instance API
------------------------------------------------

function BabbleSpell:GetTranslation(text)
	return self[text]
end

function BabbleSpell:GetStrictTranslation(text)
	local value = rawget(translations, text)
	if value == nil then
		error(MAJOR_VERSION .. ": Translation \"" .. tostring(text) .. "\" does not exist for locale " .. currentLocale, 2)
	end
	return value
end

function BabbleSpell:GetReverseTranslation(text)
	if not reverse then initReverse() end
	local translation = reverse[text]
	if not translation then
		error(MAJOR_VERSION .. ": Reverse translation for \"" .. tostring(text) .. "\" does not exist", 2)
	end
	return translation
end

function BabbleSpell:HasTranslation(text)
	return rawget(translations, text) and true
end

function BabbleSpell:HasReverseTranslation(text)
	if not reverse then initReverse() end
	return reverse[text] and true
end

function BabbleSpell:GetIterator()
	return next, translations, nil
end

function BabbleSpell:GetReverseIterator()
	if not reverse then initReverse() end
	return next, reverse, nil
end

function BabbleSpell:GetLocale()
	return currentLocale
end

function BabbleSpell:HasLocale(locale)
	return availableLocales[locale] and true
end

function BabbleSpell:IterateAvailableLocales()
	return next, availableLocales, nil
end

-- Ace3v: no-ops. AceLocale-3.0 has no strictness setting -- see the README -- and
-- no debugging mode; kept so callers of the Ace2 API do not break.
function BabbleSpell:SetStrictness()
end

function BabbleSpell:EnableDebugging()
end

function BabbleSpell:EnableDynamicLocales()
end

function BabbleSpell:Debug()
end

function BabbleSpell:GetLibraryVersion()
	return MAJOR_VERSION, MINOR_VERSION
end

------------------------------------------------
-- Spell icons
------------------------------------------------

function BabbleSpell:GetSpellIcon(spell)
	argCheck(spell, 2, "string")
	local icon = spellIcons[spell] or spellIcons[self:HasReverseTranslation(spell) and self:GetReverseTranslation(spell) or false]
	if not icon then
		return nil
	end
	return "Interface\\Icons\\" .. icon
end

function BabbleSpell:GetShortSpellIcon(spell)
	argCheck(spell, 2, "string")
	return spellIcons[spell] or spellIcons[self:HasReverseTranslation(spell) and self:GetReverseTranslation(spell) or false]
end

-- Ace3v: the same icon comes back in several shapes: "Interface\\Icons\\X" on
-- 1.12.1, "/Game/Interface/Icons/X_TEX" (UnitBuff, UnitDebuff) or
-- "Interface/Icons/X" (GetActionTexture) on Unreal Azeroth. Reduced to the bare
-- name in lower case, any two of them compare equal.
function BabbleSpell:GetIconKey(texture)
	if type(texture) ~= "string" then
		return nil
	end
	local _, _, name = strfind(texture, "([^/\\]*)$")
	name = strlower(name)
	name = strgsub(name, "%.[^.]*$", "")
	name = strgsub(name, "_tex$", "")
	return name
end

function BabbleSpell:IsSpellIcon(spell, texture)
	argCheck(spell, 2, "string")
	local icon = self:GetShortSpellIcon(spell)
	if not icon or type(texture) ~= "string" then
		return false
	end
	return self:GetIconKey(icon) == self:GetIconKey(texture)
end

-- Ace3v: what makes the library indexable, as `BS["Frostbolt"]`. Methods are raw
-- keys on BabbleSpell itself, so they are found before this ever runs. The
-- lookup is raw, so a miss never adds a key that HasTranslation would then see.
local warned = {}
setmetatable(BabbleSpell, {
	__index = function(self, key)
		local value = rawget(translations, key)
		if value == nil then
			if not warned[key] then
				warned[key] = true
				geterrorhandler()(MAJOR_VERSION .. ": Translation \"" .. tostring(key) .. "\" does not exist.")
			end
			return key
		end
		return value
	end,
	__tostring = function(self)
		return MAJOR_VERSION
	end,
})
